"""Native high-level counterpart of the exact entanglement.qmod original."""

import flagquantum as fq
from flagquantum import synth
from flagquantum.drawer import draw
from flagquantum.synth import CX, H, Output, QArray, QBit, allocate, qfunc


@qfunc
def bell_pair(reg: QArray[QBit]) -> None:
    H(reg[0])
    CX(reg[0], reg[1])


@qfunc
def bell(registers: Output[QArray[QBit]]) -> None:
    allocate(2, registers)
    bell_pair(registers)


@qfunc
def exercise(reg: Output[QArray[QBit]]) -> None:
    """Keep the Notebook's blank six-qubit exercise available to modify."""
    allocate(6, reg)


@qfunc
def main(reg: Output[QArray[QBit]]) -> None:
    allocate(6, reg)
    H(reg[0])
    for index in range(len(reg) - 1):
        CX(reg[index], reg[index + 1])


def run_example() -> None:
    """Build and draw the Bell example, blank exercise and GHZ solution."""
    for label, function, register in (
        ("Bell pair", bell, "registers"),
        ("Blank six-qubit exercise", exercise, "reg"),
        ("Six-qubit GHZ solution", main, "reg"),
    ):
        program = synth.synthesize(function)
        print(label)
        print(draw(program.circuit))
        result = fq.run(program)
        print(dict(program.probabilities(result, registers=(register,))))


if __name__ == "__main__":
    run_example()

"""Compare native FlagQuantum and independent Circuit amplitudes."""

import torch

import flagquantum as fq
from examples.synthesis.compare_states import compare_states
from examples.synthesis.tutorials.basics.entanglement.main import bell, exercise, main
from flagquantum import synth


def bell_reference_circuit() -> fq.Circuit:
    return fq.Circuit(2, dtype=torch.complex128).h(1).cx(1, 0)


def exercise_reference_circuit() -> fq.Circuit:
    return fq.Circuit(6, dtype=torch.complex128)


def reference_circuit() -> fq.Circuit:
    circuit = fq.Circuit(6, dtype=torch.complex128).h(5)
    for target in range(4, -1, -1):
        circuit.cx(target + 1, target)
    return circuit


def run_example() -> None:
    compare_states(synth.synthesize(bell), bell_reference_circuit(), ("registers",))
    compare_states(synth.synthesize(exercise), exercise_reference_circuit(), ("reg",))
    compare_states(synth.synthesize(main), reference_circuit(), ("reg",))


if __name__ == "__main__":
    run_example()
